<template><view class="rebate"><view v-if="!enterpriseAccess" class="card"><text class="heading">企业采购返利</text><text class="hint">请先完成企业认证，或接受企业负责人的邀请后查看企业返利。</text><button class="ui-button" @click="go('enterprise-apply')">查看企业认证</button><button class="ui-button" @click="go('company')">加入企业或刷新状态</button></view><view class="card" v-else-if="error">{{error}}<button class="ui-button" @click="load">重试</button></view><template v-if="enterpriseAccess&&data"><view class="card"><text class="heading">企业采购返利</text><view>可抵采购款：¥{{money(Math.max(0,data.available))}}</view><view v-if="data.available<0">退款待抵扣：¥{{money(-data.available)}}</view><text class="hint">归企业独立记账，在普通采购付款时可抵扣；不计入个人余额或分销佣金。</text><button class="ui-button" @click="go('business')">去采购</button></view><view class="card"><text class="heading">月度结算</text><view class="line" v-for="p in data.periods" :key="p.period"><view>{{p.period}} · {{states[p.status]}}</view><view>返利 ¥{{money(p.amount)}}</view><text class="hint">{{p.note}}</text></view><text v-if="!data.periods.length" class="hint">暂无结算月份。</text></view><view class="card"><text class="heading">返利明细</text><view class="line" v-for="r in data.ledger" :key="r.id"><view>{{r.note}} · ¥{{money(r.delta)}}</view><text class="hint">{{r.period||''}} {{r.created_at}}</text></view></view></template></view></template>
<script>
import {refreshOnTick} from '../services/panel-refresh'
import {request,money,go} from '../services/shop'
export default {mixins:[refreshOnTick()],props:{enterpriseAccess:Boolean},data(){return{data:null,error:'',states:{waiting:'等待结算日',held:'售后处理中，暂挂',settled:'已结算'}}},mounted(){this.load()},methods:{money,go,async load(){if(!this.enterpriseAccess){this.data=null;this.error='';return}try{this.data=await request('/company/rebate');this.error=''}catch(e){this.error=e.message}}}}
</script><style scoped>
@import '../styles/component-base.css';
.rebate{padding:16px;font-size:16px}.card{background:var(--shop-surface, #fdfeff);padding:16px;border-radius:12px;margin-bottom:14px;line-height:1.9}.heading{font-size:20px;font-weight:bold}.hint{color:var(--shop-ink, #28546c);font-size:14px;display:block}.line{padding:12px 0;border-bottom:1px solid var(--shop-border, #d5e6ee)}button{font-size:16px;background:var(--shop-accent, #c7e8f5);color:var(--shop-ink, #28546c);margin-top:12px}</style>
